package org.apache.commons.cli;

import java.io.*;
import java.io.PrintWriter;
import java.io.StringWriter;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.Iterator;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class HelpFormatter_renderWrappedText_TriageGen2Test {

    private HelpFormatter formatter;

    @Before
    public void setUp() {
        formatter = new HelpFormatter();
        formatter.setNewLine("\n");
    }

    @Test
    public void testRenderWrappedText_EmptyString() {
        StringBuffer sb = new StringBuffer();
        int width = 10;
        int nextLineTabStop = 4;
        String text = "";
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("", sb.toString());
    }

    @Test
    public void testRenderWrappedText_ShorterThanWidth() {
        StringBuffer sb = new StringBuffer();
        int width = 10;
        int nextLineTabStop = 4;
        String text = "short";
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("short\n", sb.toString());
    }

    @Test
    public void testRenderWrappedText_EqualToWidth() {
        StringBuffer sb = new StringBuffer();
        int width = 10;
        int nextLineTabStop = 4;
        String text = "exactly10";
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("exactly10\n", sb.toString());
    }

    @Test
    public void testRenderWrappedText_WrapSingleLongWord() {
        StringBuffer sb = new StringBuffer();
        int width = 5;
        int nextLineTabStop = 4;
        String text = "longword";
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("longwo\n    rd\n", sb.toString());
    }

    @Test
    public void testRenderWrappedText_MultipleWrapPoints() {
        StringBuffer sb = new StringBuffer();
        int width = 10;
        int nextLineTabStop = 4;
        String text = "multiplewrappoints";
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("multiple\n    wrapp\n    oints\n", sb.toString());
    }

    @Test
    public void testRenderWrappedText_WithSpaces() {
        StringBuffer sb = new StringBuffer();
        int width = 10;
        int nextLineTabStop = 4;
        String text = "spaces in text";
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("spaces in\n    text\n", sb.toString());
    }

    @Test
    public void testRenderWrappedText_WithWhitespace() {
        StringBuffer sb = new StringBuffer();
        int width = 10;
        int nextLineTabStop = 4;
        String text = "whitespace   ";
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("whitespace\n", sb.toString());
    }

    @Test
    public void testRenderWrappedText_MultipleLines() {
        StringBuffer sb = new StringBuffer();
        int width = 10;
        int nextLineTabStop = 4;
        String text = "lineone\nlinetwo\nlinethree";
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("lineone\n    linetwo\n    linethree\n", sb.toString());
    }

    @Test
    public void testRenderWrappedText_NonBreakingSpaces() {
        StringBuffer sb = new StringBuffer();
        int width = 10;
        int nextLineTabStop = 4;
        String text = "non\u00A0breaking\u00A0spaces";
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("non\u00A0breakin\u00A0g\n    spaces\n", sb.toString());
    }

    @Test
    public void testRenderWrappedText_WidthZero() {
        StringBuffer sb = new StringBuffer();
        int width = 0;
        int nextLineTabStop = 4;
        String text = "zero width";
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("\n", sb.toString());
    }

    @Test
    public void testRenderWrappedText_NextLineTabStopZero() {
        StringBuffer sb = new StringBuffer();
        int width = 10;
        int nextLineTabStop = 0;
        String text = "no tab";
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("no tab\n", sb.toString());
    }

    @Test
    public void testRenderWrappedText_MaxWidth() {
        StringBuffer sb = new StringBuffer();
        int width = Integer.MAX_VALUE;
        int nextLineTabStop = 4;
        String text = "max width test";
        formatter.renderWrappedText(sb, width, nextLineTabStop, text);
        assertEquals("max width test\n", sb.toString());
    }
}
